entity.extra-code-model:

public com.educaflow.subsystem.common.db.CentroUsuario getCentroUsuario(com.educaflow.subsystem.common.db.Centro centro) {
    if (centro == null || centro.getId() == null || centroUsuarios == null) {
        return null;
    }
    return centroUsuarios.stream()
        .filter(cu -> cu.getCentro() != null && centro.getId().equals(cu.getCentro().getId()))
        .findFirst()
        .orElse(null);
}

public boolean perteneceAlCentro(com.educaflow.subsystem.common.db.Centro centro) {
    return getCentroUsuario(centro) != null;
}

/** Si tiene ese tipo de usuario en alguno de sus centros. */
public boolean tieneTipoUsuario(com.educaflow.subsystem.common.db.TipoUsuarioCodigo codigoTipoUsuario) {
    if (centroUsuarios == null) {
        return false;
    }
    return centroUsuarios.stream().anyMatch(cu -> tieneTipoUsuario(cu, codigoTipoUsuario));
}

/** Si tiene ese tipo de usuario en ese centro; {@code false} si no pertenece al centro. */
public boolean tieneTipoUsuario(com.educaflow.subsystem.common.db.Centro centro, com.educaflow.subsystem.common.db.TipoUsuarioCodigo codigoTipoUsuario) {
    com.educaflow.subsystem.common.db.CentroUsuario centroUsuario = getCentroUsuario(centro);
    return centroUsuario != null && tieneTipoUsuario(centroUsuario, codigoTipoUsuario);
}

private static boolean tieneTipoUsuario(com.educaflow.subsystem.common.db.CentroUsuario centroUsuario, com.educaflow.subsystem.common.db.TipoUsuarioCodigo codigoTipoUsuario) {
    if (centroUsuario.getCentroUsuarioTipoUsuario() == null) {
        return false;
    }
    return centroUsuario.getCentroUsuarioTipoUsuario().stream()
        .map(com.educaflow.subsystem.common.db.CentroUsuarioTipoUsuario::getTipoUsuario)
        .filter(java.util.Objects::nonNull)
        .anyMatch(tipoUsuario -> tipoUsuario.getCodigo() == codigoTipoUsuario);
}
